<?php
/**
 * WebMCP: read-only tools registered in the visitor's browser (document.modelContext.registerTool), so an AI
 * agent working in the browser on ranatec.com can search and read the catalogue without scraping the page.
 * The tools live in public/webmcp.js (generated by tools/build_static.py) and read the same-origin /agent/v1 API.
 * Nothing is submitted through them: quotes and enquiries stay with the MCP server (request_quote / submit_inquiry).
 *
 * Switch: Tools → Ranatec Agent API → "Register WebMCP tools" (option ranatec_api_webmcp_enabled, default on).
 * Optional: a Chrome origin-trial token (option ranatec_api_webmcp_ot_token), printed as
 * <meta http-equiv="origin-trial">, so visitors' Chrome has WebMCP without a flag while the trial runs.
 */
if (!defined('ABSPATH')) {
    exit;
}

class Ranatec_Agent_WebMCP
{
    const OPTION_ENABLED = 'ranatec_api_webmcp_enabled';
    const OPTION_OT_TOKEN = 'ranatec_api_webmcp_ot_token';
    const FILE = 'webmcp.js';

    public static function init()
    {
        add_action('wp_head', [__CLASS__, 'head'], 1);
    }

    public static function enabled()
    {
        return get_option(self::OPTION_ENABLED, '1') !== '0';
    }

    /** On, and the build contains the script. */
    public static function active()
    {
        return self::enabled() && is_readable(RANATEC_API_PUBLIC . self::FILE);
    }

    public static function script_url()
    {
        return plugins_url('public/' . self::FILE, RANATEC_API_DIR . 'ranatec-api.php') . '?ver=' . rawurlencode(RANATEC_API_VERSION);
    }

    /** Origin-trial tokens are base64; anything else is not printed. */
    public static function token()
    {
        $t = trim((string) get_option(self::OPTION_OT_TOKEN, ''));
        return preg_match('#^[A-Za-z0-9+/=]{20,4096}$#', $t) ? $t : '';
    }

    /** The tags for a page head: the origin-trial meta (must come before the script runs) and the script. */
    public static function tags()
    {
        if (!self::active()) {
            return '';
        }
        $out = '';
        if (($t = self::token()) !== '') {
            $out .= '<meta http-equiv="origin-trial" content="' . esc_attr($t) . "\" />\n";
        }
        return $out . '<script src="' . esc_url(self::script_url()) . "\" defer data-ranatec-webmcp></script>\n";
    }

    public static function head()
    {
        echo self::tags();
    }

    /** Cache key part for the /agent/ page, which carries the tags too. */
    public static function page_variant()
    {
        return self::active() ? 'webmcp:' . md5(self::tags()) : 'no-webmcp';
    }

    /** Adds the tags to the static /agent/ page (served by the plugin, outside the theme's wp_head). */
    public static function filter_page($html)
    {
        $tags = self::tags();
        if ($tags === '' || strpos((string) $html, 'data-ranatec-webmcp') !== false) {
            return (string) $html;
        }
        $pos = stripos((string) $html, '</head>');
        return $pos === false ? (string) $html : substr($html, 0, $pos) . $tags . substr($html, $pos);
    }
}
